        return milestones.stream().map(Milestone::getPct).reduce(BigDecimal.ZERO, BigDecimal::add);
    }
    /** Whether the invoice is billed by milestones once sent: only its reached milestones are then owed. */
    public boolean isBilledByMilestones() {
        return !milestones.isEmpty() && status == InvoiceStatus.SENT;
    }
    /** Whether the sent invoice has milestones still to be reached. */
    public boolean hasPendingMilestones() {
        return isBilledByMilestones() && milestones.stream().anyMatch(m -> !m.isReached());
    }
    /**
     * Each milestone's amount at the tax rate, in the order of the milestones: its percentage of what the
     * client pays ({@link #owedTotal}, the grand total less the withholding), rounded down to the cent, except
     * the last milestone, which takes whatever is left of the milestones' share of it (rounded half up) so they
     * add up exactly.
     */
    public List<BigDecimal> milestoneAmounts(BigDecimal taxRate) {
        int scale = scale();
        BigDecimal units = owedTotal(taxRate).movePointRight(scale);
        BigDecimal hundred = BigDecimal.valueOf(100);
        int n = milestones.size();
        List<BigDecimal> amounts = new ArrayList<>(n);
        if (n == 0) {
            return amounts;
        }
        BigInteger target = units.multiply(milestonesPct()).divide(hundred).setScale(0, RoundingMode.HALF_UP)
                .toBigInteger();
        BigInteger sum = BigInteger.ZERO;
        for (int k = 0; k < n - 1; k++) {
            BigInteger floor = units.multiply(milestones.get(k).getPct()).divide(hundred)
                    .setScale(0, RoundingMode.FLOOR).toBigInteger();
            sum = sum.add(floor);
            amounts.add(new BigDecimal(floor).movePointLeft(scale).setScale(scale));
        }
        amounts.add(new BigDecimal(target.subtract(sum)).movePointLeft(scale).setScale(scale));
        return amounts;
    }
    /** What the reached milestones add up to at the tax rate. */
    public BigDecimal reachedTotal(BigDecimal taxRate) {
        List<BigDecimal> amounts = milestoneAmounts(taxRate);
        BigDecimal sum = zero();
        for (int k = 0; k < milestones.size(); k++) {
            if (milestones.get(k).isReached()) {
                sum = sum.add(amounts.get(k));
            }
        }
        return sum;
    }
    /** The standard days after it is reached a milestone falls due when the client has no payment terms. */
    public static final int MILESTONE_TERMS_DAYS = 14;
    /**
     * The day a reached milestone falls due: the client's payment terms (their own, else their region's)
     * after the day it was reached, or {@link #MILESTONE_TERMS_DAYS} days when they have none; null while
     * it is pending.
     */
    public LocalDate milestoneDueDate(Milestone milestone) {
        if (!milestone.isReached()) {
            return null;
        }
        return milestone.getReachedOn().plusDays(clientTermsDays == null ? MILESTONE_TERMS_DAYS : clientTermsDays);
    }
    /** The share of a HIGH-risk client's draft's grand total its deposits must cover before it is sent. */
    private static final BigDecimal DEPOSIT_SHARE = new BigDecimal("0.30");

    /**
     * Why the draft of a HIGH payment risk client cannot be sent yet, or null when it can: the deposits
     * held for it, at what they are worth in the client's currency (after any conversion fee or card
     * surcharge), must add up to at least 30% of its grand total.
     */
    private String depositRefusal(Invoice invoice) {
        if (riskOf(invoice.getClientId()).band() != RiskBand.HIGH) {
            return null;
        }
        Map<String, Long> drafts = draftsByReference(invoice.getClientId());
        BigDecimal held = payments.findForClient(invoice.getClientId()).stream()
                .filter(p -> invoice.getId().equals(heldFor(p, drafts)))
                .map(Payment::credit).filter(c -> c.signum() > 0)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        BigDecimal needed = invoice.total(taxRate.percent()).multiply(DEPOSIT_SHARE)
                .setScale(invoice.scale(), RoundingMode.CEILING);
        if (held.compareTo(needed) >= 0) {
            return null;
        }
        Currency currency = invoice.currency();
        return "The client pays slowly (HIGH payment risk): deposits of at least " + currency.format(needed)
                + " (30% of the grand total) must be held for this invoice before it is sent; "
                + currency.format(held) + " is held.";
    }

    /**
     * Why sending the draft would take its client over its credit limit, or null when it would not or the
     * client has no limit: the client's balance less what is in dispute (see {@link #creditBalance}) plus what its other
     * approved drafts will add (see {@link #committed}) plus what the invoice adds to it (its grand total, priced
     * as it would be sent, less the withholding) must not be over the limit.
     */
    private String creditLimitRefusal(Invoice invoice) {
        Client client = clients.findById(invoice.getClientId()).orElse(null);
        if (client == null || client.getCreditLimit() == null) {
            return null;
        }
        repriceFromRates(invoice, null, today.date());
        BigDecimal after = creditBalance(client.getId()).add(committed(client.getId(), invoice.getId()))
                .add(invoice.owedTotal(taxRate.percent()));
        BigDecimal limit = creditLimitOf(client);
        if (after.compareTo(limit) <= 0) {
            return null;
        }
        Currency currency = client.getCurrency();
        return "Sending this invoice would take " + client.getName() + "'s balance (less what is in dispute, plus its approved drafts) to " + currency.format(after)
                + ", over its " + currency.format(limit) + " credit limit"
                + (limit.compareTo(client.getCreditLimit()) == 0 ? "." : " (half of its " + currency.format(client.getCreditLimit()) + " limit, as a HIGH payment risk).");
    }

    /**
     * Why the draft credit note cannot be issued, or null when it can: its original must be a sent
     * invoice (not void). On a plan it comes off the instalments to come, so the plan must have no
     * overdue instalment and the credit note cannot be more than the principal still owed before them.
     */
    private String creditNoteRefusal(Invoice note) {
        return creditNoteRefusal(note, true);
    }

